PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?game
WHERE {
  ?character VideoGameOntology:isCharacterInGame ?game .
}

PREFIX v1: <http://example.org/v1#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX schema1: <http://schema.org/>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?productOrService
WHERE {
  ?productOrService a v1:ProductOrService .
  FILTER EXISTS {
    ?gameProduct a VideoGameOntology:GameProduct ;
                 rdfs:subClassOf ?productOrService .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?description
WHERE {
  VideoGameOntology:Completion rdfs:subClassOf VideoGameOntology:Achievement ;
                               rdfs:comment ?description .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?loseEvent ?impact
WHERE {
  ?loseEvent rdf:type VideoGameOntology:LoseEvent .
  ?loseEvent rdfs:subClassOf VideoGameOntology:GameEvent .
  OPTIONAL { ?loseEvent VideoGameOntology:impactOnPlayerExperience ?impact . }
}

