PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?player (AVG(?sessionDuration) AS ?averageSessionDuration)
WHERE {
  ?player a VideoGameOntology:Player ;
          VideoGameOntology:username ?username .
  ?session VideoGameOntology:startTime ?startTime ;
           VideoGameOntology:endTime ?endTime ;
           VideoGameOntology:username ?username .
  BIND(xsd:dateTime(?endTime) - xsd:dateTime(?startTime) AS ?duration)
  BIND(?duration / "PT1M"^^xsd:duration AS ?sessionDuration)
}
GROUP BY ?player
ORDER BY DESC(?averageSessionDuration)

