PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX VideoGameOntology: <http://example.com/videogameontology#>

SELECT ?player
WHERE {
  ?achievementUnlockEvent rdf:type VideoGameOntology:InstantaneousEvent ;
                          VideoGameOntology:unlocksAchievement ?achievement ;
                          VideoGameOntology:isEventInGame ?game .
  ?inAppPurchaseEvent rdf:type VideoGameOntology:InAppPurchaseEvent ;
                      VideoGameOntology:purchasesGameOffering ?gameProduct ;
                      VideoGameOntology:isEventInGame ?game .
  ?playerEvent rdf:type VideoGameOntology:PlayerEvent ;
               VideoGameOntology:isEventInGame ?game .
  FILTER(?achievementUnlockEvent != ?inAppPurchaseEvent)
  BIND(?playerEvent AS ?player)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>

SELECT (COUNT(?inAppPurchase) AS ?numberOfInAppPurchases) (COUNT(?achievement) AS ?numberOfAchievementsUnlocked)
WHERE {
  ?playerEvent rdf:type VideoGameOntology:PlayerEvent .
  ?inAppPurchaseEvent rdf:type VideoGameOntology:InAppPurchaseEvent ;
                      VideoGameOntology:purchasesGameOffering ?gameProduct ;
                      VideoGameOntology:isEventInGame ?game .
  ?instantaneousEvent rdf:type VideoGameOntology:InstantaneousEvent ;
                      VideoGameOntology:unlocksAchievement ?achievement ;
                      VideoGameOntology:isEventInGame ?game .
  FILTER(?playerEvent = ?inAppPurchaseEvent || ?playerEvent = ?instantaneousEvent)
}
GROUP BY ?playerEvent

